package com.mylog.journal.application;

import java.text.Normalizer;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Validates structured text generated by the LLM companion (stage 4a).
 * Note: immediate actions, chips, and nextState are chosen by deterministic code in
 * {@code TemplateCompanionResponder}, never by the LLM, so this validator only checks
 * generated copy ({@code reply}, {@code questions}, {@code suggestedTitle}).
 */
public final class CompanionOutputValidator {
    private static final int MAX_REPLY_LENGTH = 400;
    private static final int MAX_QUESTION_LENGTH = 200;
    private static final int MAX_QUESTIONS = 3;
    private static final int MAX_TITLE_LENGTH = 160;

    private static final Pattern SENTENCE_SPLIT = Pattern.compile("[.!?…]+(?:\\s+|$)");
    private static final Pattern QUOTED_EXCERPT = Pattern.compile("[\"\u201C]([^\"\u201D]{6,160})[\"\u201D]");
    /**
     * Checked against the original text (lowercased, NFC) so Vietnamese tone marks still tell words
     * apart: "tự tử" (forbidden) vs "từ từ" (a common, gentle phrase the companion should be able to use).
     */
    private static final List<String> FORBIDDEN_WITH_DIACRITICS = List.of(
            "chẩn đoán", "trầm cảm nặng", "rối loạn tâm thần", "kê đơn", "thuốc điều trị", "uống thuốc",
            "liệu trình", "trị liệu", "đường dây nóng", "tự tử", "tự sát", "tự làm đau");

    /**
     * Checked against the text with diacritics stripped, to also catch output written without tone
     * marks. Only terms that cannot collide with an innocent word once the marks are gone belong here
     * — never short ones like "tu tu" (= "tự tử" but also "từ từ").
     */
    private static final List<String> FORBIDDEN_WITHOUT_DIACRITICS = List.of(
            "chan doan", "tram cam nang", "roi loan tam than", "thuoc dieu tri", "uong thuoc",
            "duong day nong", "tu lam dau", "hotline", "1900", "1800", "http://", "https://", "www.",
            "diagnos", "prescri", "treatment plan", "medication", "suicide");

    /** Unaccented spellings that are only ambiguous when the source already had tone marks. */
    private static final Pattern UNACCENTED_SELF_HARM = Pattern.compile("(^|[^\\p{L}])tu (tu|sat)($|[^\\p{L}])");

    private CompanionOutputValidator() {}

    public static void validate(String reply, List<String> questions, String suggestedTitle, String draftText) {
        if (reply == null || reply.isBlank() || reply.length() > MAX_REPLY_LENGTH || hasControlChars(reply)) {
            throw new InvalidCompanionOutputException();
        }
        if (countSentences(reply.trim()) > 2) {
            throw new InvalidCompanionOutputException();
        }
        if (questions == null || questions.size() > MAX_QUESTIONS) {
            throw new InvalidCompanionOutputException();
        }
        for (String q : questions) {
            if (q == null || q.isBlank() || q.length() > MAX_QUESTION_LENGTH || hasControlChars(q)) {
                throw new InvalidCompanionOutputException();
            }
            checkForbiddenContent(q);
            checkQuotedExcerptsExistInDraft(q, draftText);
        }
        if (suggestedTitle != null) {
            if (suggestedTitle.isBlank() || suggestedTitle.length() > MAX_TITLE_LENGTH || hasControlChars(suggestedTitle)) {
                throw new InvalidCompanionOutputException();
            }
            checkForbiddenContent(suggestedTitle);
        }
        checkForbiddenContent(reply);
        checkQuotedExcerptsExistInDraft(reply, draftText);
    }

    private static int countSentences(String text) {
        String[] parts = SENTENCE_SPLIT.split(text);
        int count = 0;
        for (String part : parts) {
            if (!part.isBlank()) count++;
        }
        return Math.max(1, count);
    }

    private static void checkForbiddenContent(String value) {
        String lower = Normalizer.normalize(value.toLowerCase(Locale.ROOT), Normalizer.Form.NFC)
                .replace('\n', ' ');
        for (String term : FORBIDDEN_WITH_DIACRITICS) {
            if (lower.contains(term)) throw new InvalidCompanionOutputException();
        }
        // "tu tu"/"tu sat" typed literally without marks: in the original text "từ từ" keeps its marks,
        // so a bare ASCII match here can only be the unaccented spelling of self-harm wording.
        if (UNACCENTED_SELF_HARM.matcher(lower).find()) throw new InvalidCompanionOutputException();

        String folded = Normalizer.normalize(lower, Normalizer.Form.NFD)
                .replaceAll("\\p{M}", "")
                .replace('đ', 'd');
        for (String term : FORBIDDEN_WITHOUT_DIACRITICS) {
            if (folded.contains(term)) throw new InvalidCompanionOutputException();
        }
    }

    private static void checkQuotedExcerptsExistInDraft(String generatedText, String draftText) {
        Matcher matcher = QUOTED_EXCERPT.matcher(generatedText);
        String normalizedDraft = draftText == null ? "" : draftText.toLowerCase(Locale.ROOT);
        while (matcher.find()) {
            String excerpt = matcher.group(1).trim().toLowerCase(Locale.ROOT);
            if (normalizedDraft.isBlank() || !normalizedDraft.contains(excerpt)) {
                throw new InvalidCompanionOutputException();
            }
        }
    }

    private static boolean hasControlChars(String value) {
        return value.chars().anyMatch(c -> Character.isISOControl(c) && c != '\n' && c != '\r' && c != '\t');
    }

    public static final class InvalidCompanionOutputException extends RuntimeException {}
}
